package com.witchersbestiary.fist;
import java.util.*;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.server.MinecraftServer;import net.minecraft.server.world.ServerWorld;import net.minecraft.entity.*;import net.minecraft.util.math.*;import net.minecraft.text.Text;
public final class FistFights{
 public record Active(ServerPlayerEntity player,FistNpc npc,FistFightSession fight,Vec3d arena){}
 private record Invite(UUID npc,long expires){}
 private static final Map<MinecraftServer,Map<UUID,Active>> ACTIVE=new HashMap<>();private static final Map<UUID,Invite> INVITES=new HashMap<>();
 public static Active active(ServerPlayerEntity p){return ACTIVE.getOrDefault(p.getServer(),Map.of()).get(p.getUuid());}
 public static boolean invited(FistNpc n){long now=n.getWorld().getTime();return INVITES.values().stream().anyMatch(i->i.npc().equals(n.getUuid())&&i.expires()>=now);}
 public static boolean busy(Entity e){if(!(e.getWorld() instanceof ServerWorld w))return false;return ACTIVE.getOrDefault(w.getServer(),Map.of()).values().stream().anyMatch(a->a.player()==e||a.npc()==e);}
 public static void invite(ServerPlayerEntity p,FistNpc npc){if(active(p)!=null||busy(npc)||p.squaredDistanceTo(npc)>16)return;INVITES.put(p.getUuid(),new Invite(npc.getUuid(),p.getWorld().getTime()+200));npc.getNavigation().stop();FistRewards.get(p.getServer()).claim(p);p.sendMessage(Text.translatable("fist.witchersbestiary.invite"),false);}
 public static boolean confirm(ServerPlayerEntity p,FistNpc npc){var invite=INVITES.remove(p.getUuid());if(invite==null||!invite.npc().equals(npc.getUuid())||invite.expires()<p.getWorld().getTime()||busy(npc)||active(p)!=null||p.getWorld()!=npc.getWorld()||!p.isAlive()||!npc.isAlive()||p.isSpectator()||!p.getMainHandStack().isEmpty()||!p.getOffHandStack().isEmpty()||p.squaredDistanceTo(npc)>16)return false;
  var fight=new FistFightSession();fight.opponent.health=70+npc.tier*25;fight.opponent.maxStamina=75+npc.tier*12;fight.opponent.stamina=fight.opponent.maxStamina;ACTIVE.computeIfAbsent(p.getServer(),s->new HashMap<>()).put(p.getUuid(),new Active(p,npc,fight,npc.getPos()));npc.getNavigation().stop();npc.pose("stance",0);FistPackets.send(p,active(p));return true;}
 public static void action(ServerPlayerEntity p,FistFightSession.Action action){var a=active(p);if(a==null)return;if(action==FistFightSession.Action.IDLE){a.fight().releaseBlock(true);FistPackets.send(p,a);return;}if(action==FistFightSession.Action.QUICK&&a.fight().player.counterTicks>0)action=FistFightSession.Action.COUNTER;if(action==FistFightSession.Action.BLOCK&&a.fight().player.action==FistFightSession.Action.BLOCK)return;if(!p.getMainHandStack().isEmpty()||!p.getOffHandStack().isEmpty())return;if(!a.fight().act(true,action))return;if(action==FistFightSession.Action.DODGE)dodge(p);else if(action==FistFightSession.Action.QUICK||action==FistFightSession.Action.COUNTER)p.swingHand(net.minecraft.util.Hand.MAIN_HAND);FistPackets.send(p,a);}
 private static void dodge(LivingEntity e){var side=e.getRotationVec(1).multiply(1,0,1).normalize().rotateY((float)(Math.PI/2)).multiply(.75);if(e.getWorld().isSpaceEmpty(e,e.getBoundingBox().offset(side))){e.setVelocity(side.x,Math.min(.1,e.getVelocity().y),side.z);e.velocityModified=true;}}
 public static boolean intercept(LivingEntity victim,net.minecraft.entity.damage.DamageSource source){var attacker=source.getAttacker();if(attacker!=null&&busy(attacker))return true;if(busy(victim)&&victim.getWorld() instanceof ServerWorld w){var a=ACTIVE.getOrDefault(w.getServer(),Map.of()).values().stream().filter(s->s.npc()==victim||s.player()==victim).findFirst().orElse(null);if(a!=null)end(a,false,false);}return false;}
 public static void cancel(ServerPlayerEntity p){INVITES.remove(p.getUuid());var a=active(p);if(a!=null)end(a,false,false);}
 private static void end(Active a,boolean normal,boolean won){if(!normal)a.fight().cancel();var p=a.player();ACTIVE.getOrDefault(p.getServer(),Map.of()).remove(p.getUuid());a.npc().getNavigation().stop();a.npc().setTarget(null);a.npc().pose(normal?(won?"knockout":"victory"):"idle",60);if(normal&&won&&!a.npc().paid){int reward=new int[]{12,28,60}[a.npc().tier];if(FistRewards.get(p.getServer()).reserve(p.getUuid(),reward))a.npc().paid=true;FistRewards.get(p.getServer()).claim(p);}p.sendMessage(Text.translatable(normal?(won?"fist.witchersbestiary.win":"fist.witchersbestiary.lose"):"fist.witchersbestiary.cancelled"),false);FistPackets.send(p,null);}
 private static boolean facing(LivingEntity defender,LivingEntity attacker){return defender.getRotationVec(1).dotProduct(attacker.getPos().subtract(defender.getPos()).normalize())>.15;}
 private static void contact(LivingEntity e){if(e.getWorld() instanceof ServerWorld w){w.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,e.getX(),e.getBodyY(.7),e.getZ(),4,.1,.1,.1,.02);w.playSound(null,e.getBlockPos(),net.minecraft.sound.SoundEvents.ENTITY_PLAYER_ATTACK_STRONG,net.minecraft.sound.SoundCategory.PLAYERS,.6f,1);}}
 public static void tick(MinecraftServer s){var map=ACTIVE.get(s);if(map==null)return;for(var a:new ArrayList<>(map.values())){var p=a.player();var n=a.npc();var f=a.fight();if(p.isRemoved()||n.isRemoved()||!p.isAlive()||!n.isAlive()||p.getWorld()!=n.getWorld()||p.getPos().squaredDistanceTo(a.arena())>144||n.getPos().squaredDistanceTo(a.arena())>144){end(a,false,false);continue;}f.tick();if(f.stage==FistFightSession.Stage.FIGHTING){
  if(f.ticks%(20-n.tier*4)==0&&f.opponent.cooldown==0&&!n.isAiDisabled()&&(f.opponent.action==FistFightSession.Action.IDLE||f.opponent.action==FistFightSession.Action.BLOCK)){double distance=p.squaredDistanceTo(n);if(f.opponent.stamina<25)f.opponent.recovering=true;if(f.opponent.stamina>=55)f.opponent.recovering=false;if(f.opponent.recovering){var retreat=n.getPos().add(n.getPos().subtract(p.getPos()).normalize().multiply(2));if(retreat.squaredDistanceTo(a.arena())>64)retreat=a.arena();n.getNavigation().startMovingTo(retreat.x,retreat.y,retreat.z,.7);}else if(distance<7){int choice=n.getRandom().nextInt(10);var act=f.opponent.counterTicks>0?FistFightSession.Action.COUNTER:choice==0&&n.tier>0&&f.opponent.stamina>40?FistFightSession.Action.DODGE:choice<n.tier+1?FistFightSession.Action.BLOCK:choice>6?FistFightSession.Action.HEAVY:FistFightSession.Action.QUICK;if(f.act(false,act)){n.getNavigation().stop();if(act==FistFightSession.Action.DODGE)dodge(n);}}else n.getNavigation().startMovingTo(p,.85);}
  if(f.ticks%10==0){n.getLookControl().lookAt(p,15,15);if(p.squaredDistanceTo(n)<5)n.getNavigation().stop();if(f.opponent.action==FistFightSession.Action.BLOCK&&f.opponent.actionTicks>16)f.releaseBlock(false);}
  boolean near=p.squaredDistanceTo(n)<8&&n.canSee(p);if(f.contact(true)&&f.hit(true,near&&facing(p,n),facing(n,p)))contact(n);if(f.contact(false)&&f.hit(false,near&&facing(n,p),facing(p,n)))contact(p);n.pose(f.opponent.action.name().toLowerCase(java.util.Locale.ROOT).replace("idle","stance"),0);
 }if(f.stage==FistFightSession.Stage.FINISHED)end(a,true,f.playerWon);else if(f.stage==FistFightSession.Stage.CANCELLED)end(a,false,false);else if(s.getTicks()%5==0)FistPackets.send(p,a);}}
 public static void initialize(){FistRegistry.initialize();FistPackets.initialize();net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents.END_SERVER_TICK.register(FistFights::tick);net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents.DISCONNECT.register((h,s)->cancel(h.player));net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents.SERVER_STOPPED.register(s->{ACTIVE.remove(s);INVITES.clear();});
 net.fabricmc.fabric.api.event.player.AttackEntityCallback.EVENT.register((p,w,hand,e,hit)->{if(p instanceof ServerPlayerEntity server&&active(server)!=null){if(e==active(server).npc())action(server,FistFightSession.Action.QUICK);return net.minecraft.util.ActionResult.FAIL;}return net.minecraft.util.ActionResult.PASS;});
 net.fabricmc.fabric.api.event.player.AttackBlockCallback.EVENT.register((p,w,h,pos,direction)->busy(p)?net.minecraft.util.ActionResult.FAIL:net.minecraft.util.ActionResult.PASS);
 net.fabricmc.fabric.api.event.player.PlayerBlockBreakEvents.BEFORE.register((w,p,pos,state,entity)->!busy(p));
 net.fabricmc.fabric.api.event.player.UseItemCallback.EVENT.register((p,w,h)->busy(p)?net.minecraft.util.TypedActionResult.fail(p.getStackInHand(h)):net.minecraft.util.TypedActionResult.pass(p.getStackInHand(h)));
 net.fabricmc.fabric.api.event.player.UseBlockCallback.EVENT.register((p,w,h,hit)->busy(p)?net.minecraft.util.ActionResult.FAIL:net.minecraft.util.ActionResult.PASS);
 net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback.EVENT.register((d,r,e)->d.register(net.minecraft.server.command.CommandManager.literal("wbfight").then(net.minecraft.server.command.CommandManager.literal("cancel").executes(c->{cancel(c.getSource().getPlayerOrThrow());return 1;})).then(net.minecraft.server.command.CommandManager.literal("claim").executes(c->FistRewards.get(c.getSource().getServer()).claim(c.getSource().getPlayerOrThrow())?1:0))));}
}
